/bin/bash -lc "cd [workspace path] && python << 'EOF'
import numpy as np, cv2
d = np.load('source_pixels.npz')['rgb'].astype(int)
def redmask(fr):
    r,g,b = fr[...,0],fr[...,1],fr[...,2]
    return ((r>150)&(g<100)&(b<100)).astype(np.uint8)
# track components over time by matching centroids
prev = {}
for t in [0, 10, 20, 30, 40, 48]:
    m = redmask(d[t])
    n, lab, stats, cent = cv2.connectedComponentsWithStats(m, 8)
    big = [(stats[i,cv2.CC_STAT_AREA], tuple(cent[i].round(1)), (stats[i,0],stats[i,1],stats[i,2],stats[i,3])) for i in range(1,n) if stats[i,cv2.CC_STAT_AREA]>20]
    big.sort(reverse=True)
    print(\"frame\",t)
    for a,c,b in big[:8]: print(\"  \", a, c, b)
EOF"
